1	/**
2	 * Stripe webhook endpoint — POST /api/webhooks/stripe
3	 *
4	 * Receives the raw request body and verifies the Stripe-Signature header
5	 * using STRIPE_WEBHOOK_SECRET. Handles the events relevant to the marketplace:
6	 *   - checkout.session.completed       → mark booking as confirmed/pending
7	 *   - checkout.session.async_payment_succeeded
8	 *   - account.updated                  → keep our cached Connect status in sync
9	 *
10	 * This route is registered in app.ts BEFORE express.json() so the body stays
11	 * a Buffer (required by stripe.webhooks.constructEvent).
12	 */
13	import type { Request, Response } from "express";
14	import type Stripe from "stripe";
15	import { randomBytes } from "node:crypto";
16	import { eq, and, ne, sql } from "drizzle-orm";
17	import {
18	  db,
19	  bookingsTable,
20	  courtsTable,
21	  facilitiesTable,
22	  userProfilesTable,
23	  gamesTable,
24	  gameParticipantsTable,
25	} from "@workspace/db";
26	import { getStripe, getStripeWebhookSecret } from "../stripeClient";
27	import { logger } from "../lib/logger";
28	import {
29	  sendBookingConfirmationEmail,
30	  sendOwnerBookingNotificationEmail,
31	  sendSplitPlayerJoinedEmail,
32	  sendSplitParticipantConfirmationEmail,
33	} from "../lib/email";
34	import { sendNotification, sendAdminNotification } from "../lib/notify";
35	import { isStripeAccountReady } from "../lib/facility-status";
36	import { maybeIssueCoachTransfer } from "../lib/coach-transfer";
37	
38	export async function handleStripeWebhook(req: Request, res: Response): Promise<void> {
39	  const sigHeader = req.headers["stripe-signature"];
40	  if (!sigHeader) {
41	    res.status(400).json({ error: "Missing stripe-signature header" });
42	    return;
43	  }
44	  const signature = Array.isArray(sigHeader) ? sigHeader[0] : sigHeader;
45	
46	  let stripe: Stripe;
47	  let webhookSecret: string;
48	  try {
49	    stripe = getStripe();
50	    webhookSecret = getStripeWebhookSecret();
51	  } catch (err: any) {
52	    logger.error({ err }, "Stripe not configured for webhook");
53	    res.status(503).json({ error: "Stripe not configured" });
54	    return;
55	  }
56	
57	  if (!Buffer.isBuffer(req.body)) {
58	    logger.error(
59	      "Stripe webhook body is not a Buffer — express.json() must run AFTER this route",
60	    );
61	    res.status(400).json({ error: "Invalid body" });
62	    return;
63	  }
64	
65	  let event: Stripe.Event;
66	  try {
67	    event = stripe.webhooks.constructEvent(req.body, signature, webhookSecret);
68	  } catch (err: any) {
69	    logger.warn({ err: err?.message }, "Stripe webhook signature verification failed");
70	    res.status(400).json({ error: `Webhook Error: ${err?.message}` });
71	    return;
72	  }
73	
74	  try {
75	    switch (event.type) {
76	      case "checkout.session.completed":
77	      case "checkout.session.async_payment_succeeded": {
78	        const session = event.data.object as Stripe.Checkout.Session;
79	        await handleCheckoutCompleted(session);
80	        break;
81	      }
82	      case "checkout.session.expired": {
83	        const session = event.data.object as Stripe.Checkout.Session;
84	        await handleCheckoutExpired(session);
85	        break;
86	      }
87	      case "account.updated": {
88	        const account = event.data.object as Stripe.Account;
89	        await handleAccountUpdated(account);
90	        break;
91	      }
92	      default:
93	        logger.debug({ type: event.type }, "Stripe webhook received (unhandled)");
94	    }
95	  } catch (err) {
96	    logger.error({ err, type: event.type }, "Stripe webhook handler failed");
97	    // Still return 200 so Stripe doesn't retry indefinitely on our app errors;
98	    // bookings are already protected by /api/payments/confirm fallback.
99	  }
100	
101	  res.status(200).json({ received: true });
102	}
103	
104	// ─── Handlers ────────────────────────────────────────────────────────────────
105	
106	async function handleCheckoutCompleted(session: Stripe.Checkout.Session): Promise<void> {
107	  if (session.payment_status !== "paid") return;
108	
109	  // ── 1. Try to find a booking by stripeSessionId (covers regular and split-host payments) ──
110	  const rows = await db
111	    .select({
112	      booking: bookingsTable,
113	      courtName: courtsTable.name,
114	      courtId: courtsTable.id,
115	      courtAddress: facilitiesTable.address,
116	      courtCity: facilitiesTable.city,
117	      courtPhone: courtsTable.phone,
118	      courtImageUrl: courtsTable.imageUrl,
119	      ownerName: facilitiesTable.companyName,
120	      ownerEmail: facilitiesTable.email,
121	      instantBookingEnabled: courtsTable.instantBookingEnabled,
122	      hasSmartLock: courtsTable.hasSmartLock,
123	    })
124	    .from(bookingsTable)
125	    .leftJoin(courtsTable, eq(bookingsTable.courtId, courtsTable.id))
126	    .leftJoin(facilitiesTable, eq(courtsTable.facilityId, facilitiesTable.id))
127	    .where(eq(bookingsTable.stripeSessionId, session.id));
128	
129	  if (rows[0]) {
130	    const booking = rows[0].booking;
131	
132	    if (booking.isSplit) {
133	      // ── Split booking: this is the HOST's first payment ──────────────────
134	      // CAS: pending → awaiting_players (reserves the court slot)
135	      const updatedRows = await db
136	        .update(bookingsTable)
137	        .set({ status: "awaiting_players" })
138	        .where(and(
139	          eq(bookingsTable.stripeSessionId, session.id),
140	          eq(bookingsTable.status, "pending"),
141	        ))
142	        .returning();
143	
144	      if (updatedRows.length === 0) {
145	        // Already processed (awaiting_players or confirmed). Still mark participant paid.
146	      }
147	
148	      // Mark host participant as paid
149	      await db
150	        .update(gameParticipantsTable)
151	        .set({ paymentStatus: "paid" })
152	        .where(eq(gameParticipantsTable.stripeSessionId, session.id));
153	
154	      // Update game to awaiting_players
155	      await db
156	        .update(gamesTable)
157	        .set({ status: "awaiting_players" })
158	        .where(and(
159	          eq(gamesTable.bookingId, booking.id),
160	          eq(gamesTable.status, "pending_payment"),
161	        ));
162	
163	      // Check if somehow all slots are already paid (edge case: totalSlots=1)
164	      await maybeConfirmSplitBooking(booking.id, rows[0]);
165	      return;
166	    }
167	
168	    // ── Regular (non-split) booking ──────────────────────────────────────────
169	    // If the confirm endpoint already promoted the booking, do nothing else.
170	    if (booking.status === "confirmed") return;
171	
172	    // CAS guard: only promote if booking is still pending.
173	    const updatedRows = await db
174	      .update(bookingsTable)
175	      .set({ status: "confirmed" })
176	      .where(and(
177	        eq(bookingsTable.stripeSessionId, session.id),
178	        eq(bookingsTable.status, "pending"),
179	      ))
180	      .returning();
181	
182	    if (updatedRows.length === 0) {
183	      logger.warn(
184	        { sessionId: session.id, bookingId: booking.id, currentStatus: booking.status },
185	        "Webhook: stale checkout.session.completed — booking no longer pending, ignoring",
186	      );
187	      return;
188	    }
189	    const confirmedBooking = updatedRows[0]!;
190	
191	    // Fire the coach transfer on the canonical Stripe confirmation event.
192	    // Idempotency is guaranteed by the helper (DB CAS + Stripe idempotency_key)
193	    // so racing /payments/confirm cannot cause a duplicate transfer.
194	    if (confirmedBooking.coachId) {
195	      await maybeIssueCoachTransfer(confirmedBooking, getStripe());
196	    }
197	
198	    await db
199	      .update(courtsTable)
200	      .set({ totalBookings: sql`total_bookings + 1` })
201	      .where(eq(courtsTable.id, rows[0].booking.courtId));
202	
203	    // Generate a smart-lock access code if the court has a smart lock
204	    let smartAccessCode: string | undefined;
205	    if (rows[0].hasSmartLock) {
206	      smartAccessCode = randomBytes(3).toString("hex").toUpperCase(); // 6-char hex e.g. "A3F9C1"
207	      await db
208	        .update(bookingsTable)
209	        .set({ accessCode: smartAccessCode })
210	        .where(eq(bookingsTable.id, confirmedBooking.id));
211	    }
212	
213	    sendBookingConfirmationEmail({
214	      customerName: confirmedBooking.customerName,
215	      customerEmail: confirmedBooking.customerEmail,
216	      courtName: rows[0].courtName ?? "Kortas",
217	      courtId: rows[0].courtId ?? 0,
218	      courtAddress: rows[0].courtAddress ?? "",
219	      courtCity: rows[0].courtCity ?? "",
220	      courtPhone: rows[0].courtPhone ?? undefined,
221	      courtImageUrl: rows[0].courtImageUrl ?? undefined,
222	      date: confirmedBooking.date,
223	      startTime: confirmedBooking.startTime,
224	      endTime: confirmedBooking.endTime,
225	      totalPrice: Number(confirmedBooking.totalPrice),
226	      bookingId: confirmedBooking.id,
227	      accessCode: smartAccessCode,
228	    }).catch((err) => logger.error({ err }, "sendBookingConfirmationEmail (webhook) failed"));
229	
230	    if (rows[0].ownerEmail) {
231	      sendOwnerBookingNotificationEmail({
232	        ownerName: rows[0].ownerName ?? "Savininkas",
233	        ownerEmail: rows[0].ownerEmail,
234	        customerName: confirmedBooking.customerName,
235	        courtName: rows[0].courtName ?? "Kortas",
236	        date: confirmedBooking.date,
237	        startTime: confirmedBooking.startTime,
238	        endTime: confirmedBooking.endTime,
239	        totalPrice: Number(confirmedBooking.totalPrice),
240	        bookingId: confirmedBooking.id,
241	      }).catch((err) => logger.error({ err }, "sendOwnerBookingNotificationEmail (webhook) failed"));
242	    }
243	
244	    // Host-Pays-All: if a game is linked to this booking, flip it from pending_payment → open.
245	    await db
246	      .update(gamesTable)
247	      .set({ status: "open" })
248	      .where(and(eq(gamesTable.bookingId, confirmedBooking.id), eq(gamesTable.status, "pending_payment")));
249	
250	    return;
251	  }
252	
253	  // ── 2. No booking matched by stripeSessionId — try split participant lookup ──
254	  const [participant] = await db
255	    .select()
256	    .from(gameParticipantsTable)
257	    .where(eq(gameParticipantsTable.stripeSessionId, session.id));
258	
259	  if (!participant) {
260	    logger.warn({ sessionId: session.id }, "Webhook: no booking or participant matched session");
261	    return;
262	  }
263	
264	  // Mark this participant as paid (CAS: only if still pending)
265	  const updatedParticipants = await db
266	    .update(gameParticipantsTable)
267	    .set({ paymentStatus: "paid" })
268	    .where(and(
269	      eq(gameParticipantsTable.stripeSessionId, session.id),
270	      eq(gameParticipantsTable.paymentStatus, "pending"),
271	    ))
272	    .returning();
273	
274	  if (updatedParticipants.length === 0) {
275	    logger.debug({ sessionId: session.id }, "Webhook: split participant already paid, idempotent skip");
276	    return;
277	  }
278	
279	  const paidParticipant = updatedParticipants[0]!;
280	
281	  // Get game → booking context
282	  const [game] = await db.select().from(gamesTable).where(eq(gamesTable.id, participant.gameId));
283	  if (!game?.bookingId) {
284	    logger.warn({ participantId: participant.id }, "Webhook: split participant has no linked game/booking");
285	    return;
286	  }
287	
288	  const bookingRows = await db
289	    .select({
290	      booking: bookingsTable,
291	      courtName: courtsTable.name,
292	      courtId: courtsTable.id,
293	      courtAddress: facilitiesTable.address,
294	      courtCity: facilitiesTable.city,
295	      courtPhone: courtsTable.phone,
296	      courtImageUrl: courtsTable.imageUrl,
297	      ownerName: facilitiesTable.companyName,
298	      ownerEmail: facilitiesTable.email,
299	    })
300	    .from(bookingsTable)
301	    .leftJoin(courtsTable, eq(bookingsTable.courtId, courtsTable.id))
302	    .leftJoin(facilitiesTable, eq(courtsTable.facilityId, facilitiesTable.id))
303	    .where(eq(bookingsTable.id, game.bookingId));
304	
305	  if (!bookingRows[0]) {
306	    logger.warn({ bookingId: game.bookingId }, "Webhook: split booking not found");
307	    return;
308	  }
309	
310	  // Count paid slots for notification content
311	  const paidCountRows = await db
312	    .select({ count: sql<string>`count(*)` })
313	    .from(gameParticipantsTable)
314	    .where(and(
315	      eq(gameParticipantsTable.gameId, game.id),
316	      eq(gameParticipantsTable.status, "joined"),
317	      eq(gameParticipantsTable.paymentStatus, "paid"),
318	    ));
319	  const paidCount = parseInt(paidCountRows[0]?.count ?? "0", 10);
320	  const { booking, courtName } = bookingRows[0];
321	  const playerName = paidParticipant.userName ?? paidParticipant.userEmail ?? "Žaidėjas";
322	
323	  // Notify host that a new player joined/paid
324	  if (booking.bookerUserId) {
325	    sendNotification(
326	      booking.bookerUserId,
327	      "split_player_joined",
328	      `${playerName} prisijungė prie jūsų žaidimo!`,
329	      `Apmokėta: ${paidCount}/${booking.totalSlots ?? 1} vietų – ${courtName ?? "kortas"}, ${booking.date}`,
330	      `/bookings/${booking.id}`,
331	    ).catch(() => {});
332	
333	    sendSplitPlayerJoinedEmail({
334	      hostName: booking.customerName,
335	      hostEmail: booking.customerEmail,
336	      playerName,
337	      courtName: courtName ?? "Kortas",
338	      date: booking.date,
339	      startTime: booking.startTime,
340	      endTime: booking.endTime,
341	      paidSlots: paidCount,
342	      totalSlots: booking.totalSlots ?? 1,
343	      bookingId: booking.id,
344	    }).catch((err) => logger.error({ err }, "sendSplitPlayerJoinedEmail (webhook) failed"));
345	  }
346	
347	  // Send confirmation email to the participant
348	  if (paidParticipant.userEmail) {
349	    sendSplitParticipantConfirmationEmail({
350	      playerName,
351	      playerEmail: paidParticipant.userEmail,
352	      courtName: courtName ?? "Kortas",
353	      courtId: bookingRows[0].courtId ?? booking.courtId,
354	      date: booking.date,
355	      startTime: booking.startTime,
356	      endTime: booking.endTime,
357	      pricePerSlot: Number(booking.pricePerSlot ?? 0),
358	      bookingId: booking.id,
359	    }).catch((err) => logger.error({ err }, "sendSplitParticipantConfirmationEmail (webhook) failed"));
360	  }
361	
362	  await maybeConfirmSplitBooking(game.bookingId, bookingRows[0]);
363	}
364	
365	// ─── maybeConfirmSplitBooking ─────────────────────────────────────────────────
366	// Called after any split participant pays. If all slots are now paid, confirms
367	// the booking and opens the game.
368	async function maybeConfirmSplitBooking(
369	  bookingId: number,
370	  context: {
371	    booking: typeof bookingsTable.$inferSelect;
372	    courtName: string | null;
373	    courtId: number | null;
374	    courtAddress: string | null;
375	    courtCity: string | null;
376	    courtPhone: string | null;
377	    courtImageUrl: string | null;
378	    ownerName: string | null;
379	    ownerEmail: string | null;
380	  },
381	): Promise<void> {
382	  const { booking } = context;
383	  if (!booking.totalSlots) return;
384	
385	  const [game] = await db.select().from(gamesTable).where(eq(gamesTable.bookingId, bookingId));
386	  if (!game) return;
387	
388	  const paidRows = await db
389	    .select({ count: sql<string>`count(*)` })
390	    .from(gameParticipantsTable)
391	    .where(and(
392	      eq(gameParticipantsTable.gameId, game.id),
393	      eq(gameParticipantsTable.status, "joined"),
394	      eq(gameParticipantsTable.paymentStatus, "paid"),
395	    ));
396	
397	  const paidCount = parseInt(paidRows[0]?.count ?? "0", 10);
398	
399	  if (paidCount < booking.totalSlots) {
400	    logger.info(
401	      { bookingId, paidCount, totalSlots: booking.totalSlots },
402	      "Split payment: waiting for more players",
403	    );
404	    return;
405	  }
406	
407	  // All slots paid — confirm the booking
408	  const confirmed = await db
409	    .update(bookingsTable)
410	    .set({ status: "confirmed" })
411	    .where(and(
412	      eq(bookingsTable.id, bookingId),
413	      ne(bookingsTable.status, "confirmed"),
414	    ))
415	    .returning();
416	
417	  if (confirmed.length === 0) {
418	    logger.debug({ bookingId }, "Split booking already confirmed (idempotent)");
419	    return;
420	  }
421	
422	  // Open the game
423	  await db
424	    .update(gamesTable)
425	    .set({ status: "open" })
426	    .where(eq(gamesTable.id, game.id));
427	
428	  // Increment court booking count
429	  await db
430	    .update(courtsTable)
431	    .set({ totalBookings: sql`total_bookings + 1` })
432	    .where(eq(courtsTable.id, booking.courtId));
433	
434	  logger.info({ bookingId, paidCount }, "Split booking fully paid — confirmed");
435	
436	  // Notify host that all slots are filled
437	  if (booking.bookerUserId) {
438	    sendNotification(
439	      booking.bookerUserId,
440	      "split_player_joined",
441	      "Visi žaidėjai sumokėjo! 🎉",
442	      `Jūsų rezervacija ${context.courtName ?? "kortas"} (${booking.date}) patvirtinta — visi ${booking.totalSlots} žaidėjai apmokėję.`,
443	      `/bookings/${bookingId}`,
444	    ).catch(() => {});
445	  }
446	
447	  // Send confirmation email to the host (booker)
448	  sendBookingConfirmationEmail({
449	    customerName: booking.customerName,
450	    customerEmail: booking.customerEmail,
451	    courtName: context.courtName ?? "Kortas",
452	    courtId: context.courtId ?? 0,
453	    courtAddress: context.courtAddress ?? "",
454	    courtCity: context.courtCity ?? "",
455	    courtPhone: context.courtPhone ?? undefined,
456	    courtImageUrl: context.courtImageUrl ?? undefined,
457	    date: booking.date,
458	    startTime: booking.startTime,
459	    endTime: booking.endTime,
460	    totalPrice: Number(booking.totalPrice),
461	    bookingId: booking.id,
462	  }).catch((err) => logger.error({ err }, "sendBookingConfirmationEmail (split confirm) failed"));
463	
464	  if (context.ownerEmail) {
465	    sendOwnerBookingNotificationEmail({
466	      ownerName: context.ownerName ?? "Savininkas",
467	      ownerEmail: context.ownerEmail,
468	      customerName: booking.customerName,
469	      courtName: context.courtName ?? "Kortas",
470	      date: booking.date,
471	      startTime: booking.startTime,
472	      endTime: booking.endTime,
473	      totalPrice: Number(booking.totalPrice),
474	      bookingId: booking.id,
475	    }).catch((err) => logger.error({ err }, "sendOwnerBookingNotificationEmail (split) failed"));
476	  }
477	}
478	
479	async function handleCheckoutExpired(session: Stripe.Checkout.Session): Promise<void> {
480	  // Find the booking by stripeSessionId; if it's still pending, cancel it and delete any linked pending game.
481	  const [booking] = await db
482	    .select()
483	    .from(bookingsTable)
484	    .where(eq(bookingsTable.stripeSessionId, session.id));
485	
486	  if (booking) {
487	    // Only cancel if still pending — never disturb confirmed/awaiting_players bookings.
488	    await db
489	      .update(bookingsTable)
490	      .set({ status: "cancelled" })
491	      .where(and(eq(bookingsTable.id, booking.id), eq(bookingsTable.status, "pending")));
492	
493	    await db
494	      .delete(gamesTable)
495	      .where(and(eq(gamesTable.bookingId, booking.id), eq(gamesTable.status, "pending_payment")));
496	
497	    logger.info({ bookingId: booking.id, sessionId: session.id }, "stripe webhook: expired session — released hold");
498	    return;
499	  }
500	
501	  // Also handle expired split-participant sessions: remove the pending participant
502	  const [participant] = await db
503	    .select()
504	    .from(gameParticipantsTable)
505	    .where(eq(gameParticipantsTable.stripeSessionId, session.id));
506	
507	  if (participant && participant.paymentStatus === "pending") {
508	    await db
509	      .delete(gameParticipantsTable)
510	      .where(and(
511	        eq(gameParticipantsTable.id, participant.id),
512	        eq(gameParticipantsTable.paymentStatus, "pending"),
513	      ));
514	    logger.info({ participantId: participant.id }, "stripe webhook: expired split participant session — removed slot hold");
515	  }
516	}
517	
518	async function handleAccountUpdated(account: Stripe.Account): Promise<void> {
519	  const stripeComplete = isStripeAccountReady(account);
520	  logger.info(
521	    {
522	      accountId: account.id,
523	      detailsSubmitted: account.details_submitted,
524	      chargesEnabled: account.charges_enabled,
525	      payoutsEnabled: account.payouts_enabled,
526	      disabledReason: account.requirements?.disabled_reason ?? null,
527	      stripeComplete,
528	    },
529	    "stripe webhook: account.updated",
530	  );
531	  const newStatus = stripeComplete ? "active" : "pending";
532	
533	  // Owner profile is the single source of truth for Stripe readiness — payment
534	  // and submission flows read it directly. There is no per-facility cascade.
535	  const [profile] = await db
536	    .update(userProfilesTable)
537	    .set({ stripeAccountStatus: newStatus })
538	    .where(eq(userProfilesTable.stripeAccountId, account.id))
539	    .returning({ userId: userProfilesTable.userId, prevStatus: userProfilesTable.stripeAccountStatus });
540	
541	  if (!profile) return;
542	
543	  // Notify the owner so they're aware their account regressed and any new
544	  // bookings won't go through until they re-complete Stripe.
545	  if (!stripeComplete) {
546	    await sendNotification(
547	      profile.userId,
548	      "facility_rejected",
549	      "Reikia atnaujinti Stripe duomenis",
550	      "Stripe pranešė apie trūkstamą informaciją. Atnaujinkite duomenis, kad galėtumėte priimti mokėjimus.",
551	      `/owner`,
552	    ).catch(() => {});
553	  }
554	}
555

