161	const router: IRouter = Router();
162	
163	function formatBooking(
164	  booking: typeof bookingsTable.$inferSelect,
165	  courtName?: string,
166	  paidSlots?: number,
167	  // Optional joined coach profile. Callers that LEFT JOIN coachesTable on
168	  // bookings.coachId = coachesTable.userId should pass { id, name } here so
169	  // the client doesn't N+1 fetch the coach to label the booking row.
170	  coach?: { id: number; name: string } | null,
171	) {
172	  return {
173	    ...booking,
174	    totalPrice: Number(booking.totalPrice),
175	    refundAmount: Number(booking.refundAmount ?? 0),
176	    pricePerSlot: booking.pricePerSlot != null ? Number(booking.pricePerSlot) : undefined,
177	    totalSlots: booking.totalSlots ?? undefined,
178	    paidSlots: paidSlots,
179	    splitInviteToken: booking.splitInviteToken ?? undefined,
180	    rentedItems: booking.rentedItems ?? undefined,
181	    courtName: courtName ?? undefined,
182	    stripeSessionId: booking.stripeSessionId ?? undefined,
183	    stripePaymentIntentId: booking.stripePaymentIntentId ?? undefined,
184	    stripeRefundId: booking.stripeRefundId ?? undefined,
185	    managementToken: booking.managementToken ?? undefined,
186	    coach: coach ?? null,
187	  };
188	}
189	
190	router.get("/bookings", requireAuth, async (req, res): Promise<void> => {
191	  const params = ListBookingsQueryParams.safeParse(req.query);
192	  if (!params.success) {
193	    res.status(400).json({ error: params.error.message });
194	    return;
195	  }
196	
197	  const userId = getCurrentUserId(req)!;
198	  const role = await getUserRole(userId);
199	
200	  const conditions = [];
201	  if (params.data.courtId != null) {
202	    conditions.push(eq(bookingsTable.courtId, params.data.courtId));
203	  }
204	  if (params.data.status) {
205	    conditions.push(eq(bookingsTable.status, params.data.status));
206	  }
207	  if (params.data.customerEmail) {
208	    conditions.push(eq(bookingsTable.customerEmail, params.data.customerEmail));
209	  }
210	
211	  let query = db
212	    .select({
213	      booking: bookingsTable,
214	      courtName: courtsTable.name,
215	      // bookings.coachId stores the coach's Clerk userId (text), so we join
216	      // coaches.userId — not coaches.id. The select picks both: numeric coach
217	      // table id (used for /coach/:id deep links) and display name.
218	      coachInternalId: coachesTable.id,
219	      coachName: coachesTable.name,
220	    })
221	    .from(bookingsTable)
222	    .leftJoin(courtsTable, eq(bookingsTable.courtId, courtsTable.id))
223	    .leftJoin(coachesTable, eq(bookingsTable.coachId, coachesTable.userId))
224	    .$dynamic();
225	
226	  if (role === "admin") {
227	    if (conditions.length > 0) {
228	      query = query.where(and(...conditions));
229	    }
230	  } else {
231	    // "My bookings" — always scoped to the authenticated booker, regardless of
232	    // role. Owners use GET /api/owner/bookings for the facility-wide view.
233	    conditions.push(eq(bookingsTable.bookerUserId, userId));
234	    query = query.where(and(...conditions));
235	  }
236	
237	  const rows = await query;
238	
239	  // For each split booking, count paid participants (mirrors the split-status endpoint logic)
240	  const paidSlotsMap = new Map<number, number>();
241	  await Promise.all(
242	    rows
243	      .filter(r => r.booking.isSplit)
244	      .map(async r => {
245	        const [game] = await db.select({ id: gamesTable.id })
246	          .from(gamesTable)
247	          .where(eq(gamesTable.bookingId, r.booking.id));
248	        if (!game) { paidSlotsMap.set(r.booking.id, 0); return; }
249	        const participants = await db.select({ paymentStatus: gameParticipantsTable.paymentStatus })
250	          .from(gameParticipantsTable)
251	          .where(and(
252	            eq(gameParticipantsTable.gameId, game.id),
253	            eq(gameParticipantsTable.status, "joined"),
254	          ));
255	        const paid = participants.filter(p => p.paymentStatus === "paid").length;
256	        paidSlotsMap.set(r.booking.id, paid);
257	      })
258	  );
259	
260	  res.json(ListBookingsResponse.parse(rows.map(r => formatBooking(
261	    r.booking,
262	    r.courtName ?? undefined,
263	    paidSlotsMap.get(r.booking.id),
264	    r.coachInternalId != null && r.coachName != null
265	      ? { id: r.coachInternalId, name: r.coachName }
