533	export default function Bookings() {
534	  const t = useT();
535	  const [tab, setTab] = useState<"upcoming" | "past">("upcoming");
536	  const [sortKey, setSortKey] = useState<SortKey>("dateAsc");
537	  const [splitOnly, setSplitOnly] = useState(false);
538	  const [ratingBooking, setRatingBooking] = useState<{
539	    id: number; courtName?: string; courtId: number; customerName: string;
540	  } | null>(null);
541	  const [cancelTargetId, setCancelTargetId] = useState<number | null>(null);
542	
543	  const { data: bookings, isLoading } = useListBookings({});
544	  const cancelBooking = useCancelBooking();
545	  const queryClient = useQueryClient();
546	  const { toast } = useToast();
547	
548	  const handleCancelConfirmed = async (id: number) => {
549	    try {
550	      const result = await cancelBooking.mutateAsync({ id });
551	      const refunded = Number((result as any)?.refundAmount ?? 0);
552	      toast({
553	        title: t("bookings.status.cancelled"),
554	        description: refunded > 0
555	          ? t("bookings.cancel.toastRefunded").replace("{amount}", refunded.toFixed(2))
556	          : t("bookings.cancel.toastNoRefund"),
557	      });
558	      queryClient.invalidateQueries({ queryKey: getListBookingsQueryKey() });
559	      queryClient.invalidateQueries({ queryKey: ["court-activity"] });
560	      queryClient.invalidateQueries({
561	        predicate: (q) => Array.isArray(q.queryKey) && q.queryKey.some(
562	          (k) => typeof k === "string" && k.includes("/availability"),
563	        ),
564	      });
565	    } catch {
566	      toast({ title: "Klaida", variant: "destructive" });
567	    }
568	  };
569	
570	  const today = new Date();
571	  today.setHours(0, 0, 0, 0);
572	
573	  const sorted = (bookings ?? []).slice().sort((a, b) => {
574	    if (sortKey === "createdDesc" || sortKey === "createdAsc") {
575	      const ca = a.createdAt ? new Date(a.createdAt).getTime() : 0;
576	      const cb = b.createdAt ? new Date(b.createdAt).getTime() : 0;
577	      return sortKey === "createdDesc" ? cb - ca : ca - cb;
578	    }
579	    const da = new Date(a.date).getTime();
580	    const db2 = new Date(b.date).getTime();
581	    if (da !== db2) return sortKey === "dateAsc" ? da - db2 : db2 - da;
582	    return sortKey === "dateAsc"
583	      ? a.startTime.localeCompare(b.startTime)
584	      : b.startTime.localeCompare(a.startTime);
585	  });
586	
587	  const localCancelledIds: number[] = (() => {
588	    try { return JSON.parse(sessionStorage.getItem("cancelledBookingIds") ?? "[]"); } catch { return []; }
589	  })();
590	  const startMs = (b: typeof sorted[number]) => {
