interface CoachReviewDialogProps {
  open: boolean;
  onClose: () => void;
  booking: { id: number; coachId: number; coachName: string } | null;
}

function CoachReviewDialog({ open, onClose, booking }: CoachReviewDialogProps) {
  const { toast } = useToast();
  const queryClient = useQueryClient();
  const [rating, setRating] = useState(0);
  const [comment, setComment] = useState("");
  const [submitting, setSubmitting] = useState(false);

  // Reset the form whenever a new booking opens the dialog so a previous
  // submission's rating/comment never leaks into the next one.
  useEffect(() => {
    if (open) {
      setRating(0);
      setComment("");
    }
  }, [open, booking?.id]);

  const onSubmit = async () => {
    if (!booking || rating < 1 || submitting) return;
    setSubmitting(true);
    try {
      await customFetch(`${API_URL}/coach-reviews`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          bookingId: booking.id,
          coachId: booking.coachId,
          rating,
          comment: comment.trim() || null,
        }),
      });
      toast({ title: "Atsiliepimas pateiktas", description: "Ačiū, kad pasidalinote patirtimi." });
      queryClient.invalidateQueries({ queryKey: getListBookingsQueryKey() });
      queryClient.invalidateQueries({ queryKey: ["coach-reviews", String(booking.coachId)] });
      queryClient.invalidateQueries({ queryKey: ["coaches"] });
      onClose();
    } catch (err) {
      const msg = (err as { data?: { error?: string }; message?: string })?.data?.error
        ?? (err as { message?: string })?.message
        ?? "Nepavyko išsaugoti atsiliepimo";
      toast({ title: "Klaida", description: msg, variant: "destructive" });
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={(v) => { if (!v) onClose(); }}>
      <DialogContent>
        <DialogHeader>
          <DialogTitle>Palikti atsiliepimą</DialogTitle>
          <DialogDescription>
            {booking ? `Įvertinkite trenerio ${booking.coachName} treniruotę.` : ""}
          </DialogDescription>
        </DialogHeader>
        <div className="space-y-4 py-2">
          <div className="space-y-2">
            <Label className="text-xs text-muted-foreground">Įvertinimas</Label>
            <StarPicker value={rating} onChange={setRating} />
          </div>
          <div className="space-y-2">
            <Label htmlFor="coach-review-comment" className="text-xs text-muted-foreground">
              Komentaras (neprivaloma)
            </Label>
            <Textarea
              id="coach-review-comment"
              rows={4}
              value={comment}
              onChange={(e) => setComment(e.target.value.slice(0, 2000))}
              placeholder="Kaip sekėsi treniruotė? Ką labiausiai įsiminėt?"
            />
          </div>
        </div>
        <DialogFooter>
          <Button variant="ghost" onClick={onClose} disabled={submitting}>
            Atšaukti
          </Button>
          <Button onClick={onSubmit} disabled={rating < 1 || submitting}>
            {submitting && <Loader2 className="w-4 h-4 mr-1.5 animate-spin" />}
            Pateikti
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

