1	import { Router, type IRouter } from "express";
2	import { eq, and, desc, sql, isNull, isNotNull } from "drizzle-orm";
3	import { clerkClient } from "@clerk/express";
4	import {
5	  db,
6	  coachReviewsTable,
7	  coachesTable,
8	  bookingsTable,
9	} from "@workspace/db";
10	import { requireAuth, getCurrentUserId } from "../lib/auth";
11	import { vilniusToUtc } from "../lib/coach-availability";
12	import { sendCoachReviewReminderEmail } from "../lib/email";
13	import { logger } from "../lib/logger";
14	import { z } from "zod";
15	
16	const router: IRouter = Router();
17	
18	const CreateReviewBody = z.object({
19	  bookingId: z.number().int().positive(),
20	  coachId: z.number().int().positive(),
21	  rating: z.number().int().min(1).max(5),
22	  comment: z.string().trim().min(1).max(2000).optional().nullable(),
23	});
24	
25	/**
26	 * Invariant D: recompute the (averageRating, reviewCount) aggregates from
27	 * coachReviewsTable and write them back to coachesTable so the marketplace
28	 * list query can render ratings without a sub-aggregate.
29	 *
30	 * Always called from inside the same transaction as the mutation that
31	 * triggered it, so a failed sync rolls the insert/update/delete back too.
32	 *
33	 * Note the explicit `count(id)` against `coach_reviews` rather than reading
34	 * coachesTable.reviewCount — the latter is what we're WRITING, so reading
35	 * it would create a cycle. The count(*) here scans the index on coachId.
36	 */
37	type Tx = Parameters<Parameters<typeof db.transaction>[0]>[0];
38	async function syncCoachAverageRating(coachId: number, tx: Tx): Promise<void> {
39	  const [agg] = await tx
40	    .select({
41	      avg: sql<string | null>`AVG(${coachReviewsTable.rating})::numeric(3,2)`,
42	      count: sql<number>`COUNT(${coachReviewsTable.id})::int`,
43	    })
44	    .from(coachReviewsTable)
45	    .where(and(
46	      eq(coachReviewsTable.coachId, coachId),
47	      // Hidden/flagged reviews are immediately excluded from the public
48	      // aggregate. Toggling status from the admin moderation endpoint must
49	      // therefore re-run this helper inside the same transaction.
50	      eq(coachReviewsTable.status, "published"),
51	    ));
52	
53	  await tx
54	    .update(coachesTable)
55	    .set({
56	      // Numeric column accepts a string (drizzle/postgres-js convention).
57	      averageRating: agg?.avg ?? null,
58	      reviewCount: agg?.count ?? 0,
59	    })
60	    .where(eq(coachesTable.id, coachId));
61	}
62	
63	// POST /coach-reviews — submit a verified-purchase review.
64	//
65	// Invariant C is enforced here: (1) the requesting user owns the booking,
66	// (2) the booking's coach matches the submitted coachId, (3) the booking's
67	// scheduled end (Europe/Vilnius local) is in the past, and (4) the booking
68	// is confirmed and not cancelled. The unique constraint on bookingId
69	// guarantees one-review-per-booking even under concurrent submission.
70	router.post("/coach-reviews", requireAuth, async (req, res): Promise<void> => {
71	  const userId = getCurrentUserId(req)!;
72	  const parsed = CreateReviewBody.safeParse(req.body);
73	  if (!parsed.success) {
74	    res.status(400).json({ error: "Netinkami atsiliepimo duomenys" });
75	    return;
76	  }
77	  const { bookingId, coachId, rating, comment } = parsed.data;
78	
79	  // (1) Fetch the booking and verify ownership.
80	  const [booking] = await db
81	    .select({
82	      id: bookingsTable.id,
83	      bookerUserId: bookingsTable.bookerUserId,
84	      coachUserId: bookingsTable.coachId,
85	      date: bookingsTable.date,
86	      endTime: bookingsTable.endTime,
87	      status: bookingsTable.status,
88	    })
89	    .from(bookingsTable)
90	    .where(eq(bookingsTable.id, bookingId));
91	
92	  if (!booking) {
93	    res.status(404).json({ error: "Rezervacija nerasta" });
94	    return;
95	  }
96	  if (booking.bookerUserId !== userId) {
97	    // Don't leak existence — same shape as 404 to a non-owner.
98	    res.status(404).json({ error: "Rezervacija nerasta" });
99	    return;
100	  }
101	
102	  // (2) Verify the booking points to the submitted coach. bookings.coachId
103	  // is the Clerk userId, so we resolve coachesTable.id → userId here.
104	  if (!booking.coachUserId) {
105	    res.status(400).json({ error: "Ši rezervacija nėra trenerio pamoka" });
106	    return;
107	  }
108	  const [coach] = await db
109	    .select({ id: coachesTable.id, userId: coachesTable.userId })
110	    .from(coachesTable)
111	    .where(eq(coachesTable.id, coachId));
112	  if (!coach || coach.userId !== booking.coachUserId) {
113	    res.status(400).json({ error: "Rezervacija nesutampa su nurodytu treneriu" });
114	    return;
115	  }
116	
117	  // (3) Booking must be over — convert YYYY-MM-DD + HH:MM (Vilnius local) to UTC.
118	  const endUtc = vilniusToUtc(booking.date, booking.endTime).getTime();
119	  if (endUtc > Date.now()) {
120	    res.status(400).json({ error: "Atsiliepimą galima palikti tik po treniruotės" });
121	    return;
122	  }
123	
124	  // (4) Reject cancelled/blocked bookings so refunded lessons can't be reviewed.
125	  if (booking.status === "cancelled" || booking.status === "blocked") {
126	    res.status(400).json({ error: "Atšauktos rezervacijos negali būti vertinamos" });
127	    return;
128	  }
129	
130	  // Insert + sync aggregate atomically. The unique(bookingId) constraint is
131	  // the last-line guard against double-submit; we surface its violation as
132	  // a clean 409 rather than a generic 500.
133	  try {
134	    const inserted = await db.transaction(async (tx) => {
135	      const [row] = await tx
136	        .insert(coachReviewsTable)
137	        .values({
138	          reviewerUserId: userId,
139	          coachId,
140	          bookingId,
141	          rating,
142	          comment: comment ?? null,
143	        })
144	        .returning();
145	      await syncCoachAverageRating(coachId, tx);
146	      return row;
147	    });
148	
149	    res.status(201).json({
150	      id: inserted.id,
151	      coachId: inserted.coachId,
152	      bookingId: inserted.bookingId,
153	      rating: inserted.rating,
154	      comment: inserted.comment ?? null,
155	      createdAt: inserted.createdAt.toISOString(),
156	    });
157	  } catch (err: unknown) {
158	    const code = (err as { code?: string })?.code;
159	    if (code === "23505") {
160	      res.status(409).json({ error: "Šiai rezervacijai jau pateiktas atsiliepimas" });
161	      return;
162	    }
163	    throw err;
164	  }
165	});
166	
167	// GET /coaches/:id/reviews — paginated reviews for a single coach, newest
168	// first. Joins Clerk in a single batched lookup to attach the reviewer's
169	// first name; falls back to "Vartotojas" if Clerk is unavailable.
170	router.get("/coaches/:id/reviews", async (req, res): Promise<void> => {
171	  const coachId = parseInt(String(req.params.id), 10);
172	  if (isNaN(coachId)) {
173	    res.status(400).json({ error: "Invalid coach id" });
174	    return;
175	  }
176	  const rawLimit = Number(req.query.limit ?? 20);
177	  const limit = Number.isFinite(rawLimit) ? Math.min(Math.max(Math.trunc(rawLimit), 1), 50) : 20;
178	  const rawOffset = Number(req.query.offset ?? 0);
179	  const offset = Number.isFinite(rawOffset) ? Math.max(Math.trunc(rawOffset), 0) : 0;
180	
181	  const rows = await db
182	    .select({
183	      id: coachReviewsTable.id,
184	      reviewerUserId: coachReviewsTable.reviewerUserId,
185	      rating: coachReviewsTable.rating,
186	      comment: coachReviewsTable.comment,
187	      createdAt: coachReviewsTable.createdAt,
188	    })
189	    .from(coachReviewsTable)
190	    .where(eq(coachReviewsTable.coachId, coachId))
191	    .orderBy(desc(coachReviewsTable.createdAt))
192	    .limit(limit)
193	    .offset(offset);
194	
195	  // Batch-resolve reviewer first names from Clerk. Best-effort — if Clerk is
196	  // unreachable we fall back to a generic label rather than blocking the
197	  // page render.
198	  const userIds = Array.from(new Set(rows.map((r) => r.reviewerUserId)));
199	  const nameByUserId = new Map<string, string>();
200	  if (userIds.length > 0) {
201	    try {
202	      const list = await clerkClient.users.getUserList({ userId: userIds, limit: userIds.length });
203	      for (const u of list.data) {
204	        const first = (u.firstName ?? "").trim();
205	        const last = (u.lastName ?? "").trim();
206	        const initial = last ? `${last[0]}.` : "";
207	        const display = [first, initial].filter(Boolean).join(" ");
208	        nameByUserId.set(u.id, display || "Vartotojas");
209	      }
210	    } catch {
211	      // Clerk unavailable — leave the map empty so the fallback applies below.
212	    }
213	  }
214	
215	  // Pull the totals from the denormalized aggregate to avoid a second query.
216	  const [agg] = await db
217	    .select({
218	      averageRating: coachesTable.averageRating,
219	      reviewCount: coachesTable.reviewCount,
220	    })
221	    .from(coachesTable)
222	    .where(eq(coachesTable.id, coachId));
223	
224	  res.json({
225	    coachId,
226	    averageRating: agg?.averageRating != null ? Number(agg.averageRating) : null,
227	    reviewCount: agg?.reviewCount ?? 0,
228	    items: rows.map((r) => ({
229	      id: r.id,
230	      rating: r.rating,
231	      comment: r.comment ?? null,
232	      reviewerName: nameByUserId.get(r.reviewerUserId) ?? "Vartotojas",
233	      createdAt: r.createdAt.toISOString(),
234	    })),
235	    limit,
236	    offset,
237	  });
238	});
239	
240	/**
241	 * Compute "yesterday" in Europe/Vilnius local time as a YYYY-MM-DD string.
242	 * Using Intl.DateTimeFormat with the explicit timeZone handles DST correctly
243	 * — we can't just subtract 86_400_000 because Vilnius shifts twice a year.
244	 */
245	function vilniusYesterdayDateStr(): string {
246	  const fmt = new Intl.DateTimeFormat("en-CA", {
247	    timeZone: "Europe/Vilnius",
248	    year: "numeric",
249	    month: "2-digit",
250	    day: "2-digit",
251	  });
252	  const todayStr = fmt.format(new Date()); // already YYYY-MM-DD in Vilnius
253	  const [y, m, d] = todayStr.split("-").map(Number);
254	  // Subtract one calendar day. Day "0" wraps to last day of previous month.
255	  const dt = new Date(Date.UTC(y, m - 1, d - 1));
256	  const yy = dt.getUTCFullYear();
257	  const mm = String(dt.getUTCMonth() + 1).padStart(2, "0");
258	  const dd = String(dt.getUTCDate()).padStart(2, "0");
259	  return `${yy}-${mm}-${dd}`;
260	}
261	
262	/**
263	 * Daily sweep: find coach lessons that ended yesterday (Vilnius local) and
264	 * haven't been reviewed yet, then fire the "Kaip sekėsi treniruotė?" email.
265	 * Returns the number of reminders sent — caller logs the aggregate.
266	 *
267	 * Idempotency: the sweep runs once per UTC day from cron.ts. The "yesterday
268	 * only" filter is the de-facto guard — if the cron misses a day we lose that
269	 * batch (acceptable tradeoff vs. adding a reviewReminderSentAt column).
270	 *
271	 * Guest bookings (bookerUserId IS NULL) are skipped — they have no Clerk
272	 * identity to bind a review to, so a reminder has nowhere meaningful to go.
273	 */
274	export async function sweepCoachReviewReminders(): Promise<number> {
275	  const yesterdayStr = vilniusYesterdayDateStr();
276	
277	  const rows = await db
278	    .select({
279	      bookingId: bookingsTable.id,
280	      customerName: bookingsTable.customerName,
281	      customerEmail: bookingsTable.customerEmail,
282	      date: bookingsTable.date,
283	      coachName: coachesTable.name,
284	      reviewId: coachReviewsTable.id,
285	    })
286	    .from(bookingsTable)
287	    .innerJoin(coachesTable, eq(bookingsTable.coachId, coachesTable.userId))
288	    .leftJoin(coachReviewsTable, eq(coachReviewsTable.bookingId, bookingsTable.id))
