interface CoachReviewDialogProps {
  open: boolean;
  onClose: () => void;
  // existingReviewId !== undefined puts the dialog into edit mode: submits
  // a PATCH instead of POST, seeds the rating/comment from initialRating
  // and initialComment. Null means "no existing review yet".
  booking: {
    id: number;
    coachId: number;
    coachName: string;
    existingReviewId?: number | null;
    initialRating?: number;
    initialComment?: string | null;
  } | null;
}

function CoachReviewDialog({ open, onClose, booking }: CoachReviewDialogProps) {
  const { toast } = useToast();
  const queryClient = useQueryClient();
  const [rating, setRating] = useState(0);
  const [comment, setComment] = useState("");
  const [submitting, setSubmitting] = useState(false);
  const isEdit = booking?.existingReviewId != null;

  // Seed the form whenever the dialog opens. In edit mode we pull initial
  // values from the booking; in create mode we start clean. This effect runs
  // on every (open, booking.id) change so reopening with a different row
  // never leaks the previous one's values.
  useEffect(() => {
    if (open && booking) {
      setRating(booking.initialRating ?? 0);
      setComment(booking.initialComment ?? "");
    }
  }, [open, booking?.id, booking?.initialRating, booking?.initialComment, booking]);

