// Public review feed, paginated. "Rodyti daugiau" appends the next page via
// useInfiniteQuery; each page request returns hasMore so the button hides
// when the last page lands.
const REVIEWS_PAGE_SIZE = 10;
const reviewsQ = useInfiniteQuery<ReviewsResponse, Error, ReviewsResponse, [string, string | undefined], number>({
  queryKey: ["coach-reviews", coachId],
  initialPageParam: 1,
  queryFn: ({ pageParam = 1 }) =>
    fetch(`${API}/coaches/${coachId}/reviews?page=${pageParam}&limit=${REVIEWS_PAGE_SIZE}`).then((r) =>
      r.ok
        ? r.json()
        : {
            coachId: Number(coachId),
            averageRating: null,
            reviewCount: 0,
            items: [],
            limit: REVIEWS_PAGE_SIZE,
            offset: 0,
            hasMore: false,
          },
    ),
  getNextPageParam: (last, all) => (last.hasMore ? all.length + 1 : undefined),
  enabled: !!coachId,
});
const reviewPages = reviewsQ.data?.pages ?? [];
const reviewItems = reviewPages.flatMap((p) => p.items);
const reviewMeta = reviewPages[0] ?? null;

