  coachReplyText: string | null;
  createdAt: string;
}

interface AdminReviewsResponse {
  items: AdminReviewItem[];
  hasMore: boolean;
  limit: number;
  offset: number;
}

function ReviewsPanel() {
  const qc = useQueryClient();
  const { toast } = useToast();
  const [page, setPage] = useState(1);
  const limit = 50;

  const { data, isLoading } = useQuery<AdminReviewsResponse>({
    queryKey: ["admin-coach-reviews", page],
    queryFn: () => customFetch<AdminReviewsResponse>(`/api/admin/coach-reviews?page=${page}&limit=${limit}`),
  });

  const setStatus = useMutation({
    mutationFn: async ({ id, status }: { id: number; status: "published" | "hidden" | "flagged" }) => {
      return customFetch(`/api/admin/coach-reviews/${id}/status`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ status }),
      });
    },
    onSuccess: () => {
      toast({ title: "Status'as atnaujintas" });
      qc.invalidateQueries({ queryKey: ["admin-coach-reviews"] });
      // Public marketplace aggregates may have shifted — drop the coach lists.
      qc.invalidateQueries({ queryKey: ["coaches"] });
      qc.invalidateQueries({ queryKey: ["coach-reviews"] });
    },
    onError: (err: Error) => {
      toast({ title: "Klaida", description: err.message, variant: "destructive" });
    },
  });

  const items = data?.items ?? [];

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <h2 className="text-lg font-semibold">Visi atsiliepimai</h2>
        <p className="text-xs text-muted-foreground">
          Įskaitant paslėptus ir pažymėtus. Status'o keitimas iš karto perskaičiuoja trenerio vidurkį.
        </p>
      </div>
      {isLoading ? (
        <div className="space-y-2">
          {Array.from({ length: 6 }).map((_, i) => <Skeleton key={i} className="h-20" />)}
        </div>
      ) : items.length === 0 ? (
        <div className="rounded-2xl border bg-card px-6 py-12 text-center text-sm text-muted-foreground">
          Atsiliepimų dar nėra.
        </div>
      ) : (
        <div className="space-y-2">
          {items.map((r) => (
            <div key={r.id} className="border rounded-xl bg-card p-4 space-y-2">
              <div className="flex items-start justify-between gap-3 flex-wrap">
                <div className="min-w-0 flex-1 space-y-1">
                  <div className="flex items-center gap-2 flex-wrap text-sm">
                    <Link href={`/coach/${r.coachId}`} className="font-medium hover:underline truncate">
                      {r.coachName}
                    </Link>
                    <span className="inline-flex items-center gap-0.5">
                      {Array.from({ length: 5 }, (_, i) => (
                        <Star
                          key={i}
                          className={`w-3.5 h-3.5 ${
                            i < r.rating ? "fill-amber-400 text-amber-400" : "text-muted-foreground/30"
                          }`}
                        />
                      ))}
                    </span>
                    <span className="text-xs text-muted-foreground">
                      {new Date(r.createdAt).toLocaleDateString("lt-LT", { year: "numeric", month: "short", day: "numeric" })}
                    </span>
                    <code className="text-[10px] text-muted-foreground">#{r.id}</code>
                  </div>
                  {r.comment && (
                    <p className="text-sm text-muted-foreground whitespace-pre-line">{r.comment}</p>
                  )}
                  {r.coachReplyText && (
                    <div className="text-xs text-muted-foreground italic border-l-2 border-primary/40 pl-2">
                      Trenerio atsakymas: {r.coachReplyText}
                    </div>
                  )}
                </div>
                <select
                  className="text-xs rounded-md border bg-background px-2 py-1 cursor-pointer disabled:opacity-50"
                  value={r.status}
                  disabled={setStatus.isPending}
                  onChange={(e) =>
                    setStatus.mutate({
                      id: r.id,
                      status: e.target.value as "published" | "hidden" | "flagged",
                    })
                  }
                >
                  <option value="published">Viešas</option>
                  <option value="hidden">Paslėpti</option>
                  <option value="flagged">Pažymėti</option>
                </select>
              </div>
            </div>
          ))}
          <div className="flex items-center justify-between pt-2">
            <Button
              variant="ghost"
              size="sm"
              disabled={page <= 1}
              onClick={() => setPage((p) => Math.max(1, p - 1))}
            >
              ← Atgal
            </Button>
            <span className="text-xs text-muted-foreground">Puslapis {page}</span>
            <Button
              variant="ghost"
              size="sm"
              disabled={!data?.hasMore}
              onClick={() => setPage((p) => p + 1)}
            >
              Toliau →
            </Button>
          </div>
        </div>
      )}
    </div>
  );
}

export default function AdminDashboard() {
  const { isAdmin, isLoading: roleLoading } = useRole();
  const initialTab = (): AdminTab => {
    const p = new URLSearchParams(window.location.search).get("tab");
    const valid: AdminTab[] = ["courts", "users", "facilities", "coaches", "owners", "editRequests", "reviews"];
    return valid.includes(p as AdminTab) ? (p as AdminTab) : "facilities";
  };

