177	function RateDialog({ open, onClose, booking }: RateDialogProps) {
178	  const t = useT();
179	  const [rating, setRating] = useState(0);
180	  const [reviewText, setReviewText] = useState("");
181	  const [photos, setPhotos] = useState<string[]>([]);
182	  const [uploading, setUploading] = useState(false);
183	  const fileInputRef = useRef<HTMLInputElement>(null);
184	  const createReview = useCreateReview();
185	  const { toast } = useToast();
186	
187	  const ratingLabels = ["", t("rating.1"), t("rating.2"), t("rating.3"), t("rating.4"), t("rating.5")];
188	
189	  const handlePhotoUpload = async (files: FileList) => {
190	    const remaining = 3 - photos.length;
191	    if (remaining <= 0) return;
192	    const toUpload = Array.from(files).slice(0, remaining);
193	    setUploading(true);
194	    try {
195	      for (const file of toUpload) {
196	        const fd = new FormData();
197	        fd.append("image", file);
198	        const res = await fetch(`${API_URL}/upload/court-image`, { method: "POST", body: fd });
199	        if (res.ok) {
200	          const data = await res.json();
201	          setPhotos(prev => [...prev, data.path].slice(0, 3));
202	        }
203	      }
204	    } catch {
205	      toast({ title: "Klaida", description: "Nepavyko įkelti nuotraukos", variant: "destructive" });
206	    } finally {
207	      setUploading(false);
208	    }
209	  };
210	
211	  const handleSubmit = async () => {
212	    if (!booking || rating === 0) return;
213	    try {
214	      await createReview.mutateAsync({
215	        id: booking.courtId,
216	        data: {
217	          bookingId: booking.id,
218	          rating,
219	          reviewText: reviewText.trim() || undefined,
220	          reviewerName: booking.customerName,
221	          photos: photos.length > 0 ? photos : undefined,
222	        },
223	      });
224	      toast({ title: "Ačiū už atsiliepimą! 🌟", description: "Jūsų įvertinimas išsaugotas." });
225	      setRating(0);
226	      setReviewText("");
227	      setPhotos([]);
