interface CourtReviewDialogProps {
  open: boolean;
  onClose: () => void;
  // existingReviewId !== undefined puts the dialog into edit mode and submits
  // PATCH instead of POST. Seeds rating + comment from initial* fields.
  booking: {
    id: number;
    courtId: number;
    courtName?: string;
    existingReviewId?: number | null;
    initialRating?: number;
    initialComment?: string | null;
  } | null;
}

function CourtReviewDialog({ open, onClose, booking }: CourtReviewDialogProps) {
  const { toast } = useToast();
  const queryClient = useQueryClient();
  const [rating, setRating] = useState(0);
  const [comment, setComment] = useState("");
  const [submitting, setSubmitting] = useState(false);
  const isEdit = booking?.existingReviewId != null;

  useEffect(() => {
    if (open && booking) {
      setRating(booking.initialRating ?? 0);
      setComment(booking.initialComment ?? "");
    }
  }, [open, booking?.id, booking?.initialRating, booking?.initialComment, booking]);

  const onSubmit = async () => {
    if (!booking || rating < 1 || submitting) return;
    setSubmitting(true);
    try {
      if (isEdit && booking.existingReviewId != null) {
        await customFetch(`${API_URL}/court-reviews/${booking.existingReviewId}`, {
          method: "PATCH",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ rating, comment: comment.trim() || null }),
        });
        toast({ title: "Atsiliepimas atnaujintas" });
      } else {
        await customFetch(`${API_URL}/court-reviews`, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            bookingId: booking.id,
            courtId: booking.courtId,
            rating,
            comment: comment.trim() || null,
          }),
        });
        toast({ title: "Atsiliepimas pateiktas", description: "Ačiū, kad pasidalinote patirtimi." });
      }
      queryClient.invalidateQueries({ queryKey: getListBookingsQueryKey() });
      queryClient.invalidateQueries({ queryKey: ["court-reviews", String(booking.courtId)] });
      queryClient.invalidateQueries({ queryKey: ["owner-court-reviews"] });
      queryClient.invalidateQueries({ queryKey: ["courts"] });
      onClose();
    } catch (err) {
      const msg = (err as { data?: { error?: string }; message?: string })?.data?.error
        ?? (err as { message?: string })?.message
        ?? "Nepavyko išsaugoti atsiliepimo";
      toast({ title: "Klaida", description: msg, variant: "destructive" });
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={(v) => { if (!v) onClose(); }}>
      <DialogContent>
        <DialogHeader>
          <DialogTitle>{isEdit ? "Redaguoti atsiliepimą" : "Palikti atsiliepimą"}</DialogTitle>
          <DialogDescription>
            {booking ? `Įvertinkite ${booking.courtName ?? `aikštelę #${booking.courtId}`}.` : ""}
          </DialogDescription>
        </DialogHeader>
        <div className="space-y-4 py-2">
          <div className="space-y-2">
            <Label className="text-xs text-muted-foreground">Įvertinimas</Label>
            <StarPicker value={rating} onChange={setRating} />
          </div>
          <div className="space-y-2">
            <Label htmlFor="court-review-comment" className="text-xs text-muted-foreground">
              Komentaras (neprivaloma)
            </Label>
            <Textarea
              id="court-review-comment"
              rows={4}
              value={comment}
              onChange={(e) => setComment(e.target.value.slice(0, 2000))}
              placeholder="Kokia buvo aikštelė? Ką labiausiai įsiminėt?"
            />
          </div>
        </div>
        <DialogFooter>
          <Button variant="ghost" onClick={onClose} disabled={submitting}>
            Atšaukti
          </Button>
          <Button onClick={onSubmit} disabled={rating < 1 || submitting}>
            {submitting && <Loader2 className="w-4 h-4 mr-1.5 animate-spin" />}
            {isEdit ? "Išsaugoti" : "Pateikti"}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

