// Paginated verified-purchase reviews. Same useInfiniteQuery + Load More
// pattern as /coach/:id, fetching status='published' only via the server.
interface CourtReviewItem {
  id: number;
  rating: number;
  comment: string | null;
  reviewerName: string;
  ownerReplyText: string | null;
  ownerReplyCreatedAt: string | null;
  createdAt: string;
}
interface CourtReviewsResponse {
  courtId: number;
  averageRating: number | null;
  reviewCount: number;
  items: CourtReviewItem[];
  limit: number;
  offset: number;
  hasMore: boolean;
}
const REVIEWS_PAGE_SIZE = 10;
const reviewsQ = useInfiniteQuery({
  queryKey: ["court-reviews", String(courtId)],
  initialPageParam: 1 as number,
  queryFn: async ({ pageParam }): Promise<CourtReviewsResponse> => {
    const r = await fetch(`${API}/courts/${courtId}/reviews?page=${pageParam}&limit=${REVIEWS_PAGE_SIZE}`);
    if (!r.ok) {
      return { courtId, averageRating: null, reviewCount: 0, items: [], limit: REVIEWS_PAGE_SIZE, offset: 0, hasMore: false };
    }
    return r.json() as Promise<CourtReviewsResponse>;
  },
  getNextPageParam: (last, all) => (last.hasMore ? all.length + 1 : undefined),
  enabled: !!courtId && !isNaN(courtId),
});
const reviewPages: CourtReviewsResponse[] = reviewsQ.data?.pages ?? [];
const reviews: CourtReviewItem[] = reviewPages.flatMap((p) => p.items);
const reviewMeta: CourtReviewsResponse | null = reviewPages[0] ?? null;

