}

/** Golf — flag on pole, ground cup, and ball */
export function GolfIcon(props: SvgProps) {
  const sw = props.strokeWidth ?? 1.6;
  return (
    <Svg {...props}>
      <line x1="8" y1="22" x2="8" y2="2" strokeWidth={sw} />
