import { SVGProps } from "react";

type SvgProps = SVGProps<SVGSVGElement> & { size?: number; strokeWidth?: number };

function Svg({ size = 20, strokeWidth = 1.6, children, ...props }: SvgProps) {
  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth={strokeWidth}
      strokeLinecap="round"
      strokeLinejoin="round"
      {...props}
    >
      {children}
    </svg>
  );
}

/** Tennis ball — circle with two horizontal wavy seams (the iconic tennis-
 *  ball curve). The previous left/right S-curves read as parentheses rather
 *  than the recognizable horizontal seam pattern. */
export function TennisIcon(props: SvgProps) {
  const sw = props.strokeWidth ?? 1.6;
  return (
    <Svg {...props}>
      <circle cx="12" cy="12" r="10" />
      <path d="M3 8.5 Q 12 14 21 8.5" strokeWidth={sw} fill="none" />
      <path d="M3 15.5 Q 12 10 21 15.5" strokeWidth={sw} fill="none" />
    </Svg>
  );
}

/** Basketball — circle with the classic 4-seam pattern: one horizontal seam
 *  and two side curves that bow out toward the rim (rather than running
 *  straight top-to-bottom, which read as a watermelon at small sizes). */
export function BasketballIcon(props: SvgProps) {
  const sw = props.strokeWidth ?? 1.6;
  return (
    <Svg {...props}>
      <circle cx="12" cy="12" r="10" />
      <line x1="2" y1="12" x2="22" y2="12" strokeWidth={sw} />
      <path d="M12 2 Q 4 12 12 22" strokeWidth={sw} fill="none" />
      <path d="M12 2 Q 20 12 12 22" strokeWidth={sw} fill="none" />
    </Svg>
  );
}

/** Padel racket — solid teardrop face with perforation holes (NOT strings)
 *  and a short handle with grip. Real padel rackets have no strings; the
 *  surface is solid composite with drilled holes. The previous strung-rect
 *  design was visually a tennis or squash racket. */
export function PadelIcon(props: SvgProps) {
  const sw = props.strokeWidth ?? 1.6;
  return (
    <Svg {...props}>
      {/* Teardrop / rounded-diamond face */}
      <path
        d="M12 2 C 16.5 2 19 5.5 19 9.5 C 19 13 16.5 15.5 12 15.5 C 7.5 15.5 5 13 5 9.5 C 5 5.5 7.5 2 12 2 Z"
        strokeWidth={sw}
      />
      {/* Perforation holes — filled dots so they stay visible at 11px */}
      <circle cx="9" cy="6.5" r="0.7" fill="currentColor" stroke="none" />
      <circle cx="12" cy="5.5" r="0.7" fill="currentColor" stroke="none" />
      <circle cx="15" cy="6.5" r="0.7" fill="currentColor" stroke="none" />
      <circle cx="9.5" cy="10" r="0.7" fill="currentColor" stroke="none" />
      <circle cx="12" cy="9" r="0.7" fill="currentColor" stroke="none" />
      <circle cx="14.5" cy="10" r="0.7" fill="currentColor" stroke="none" />
      <circle cx="10.5" cy="13" r="0.7" fill="currentColor" stroke="none" />
      <circle cx="13.5" cy="13" r="0.7" fill="currentColor" stroke="none" />
      {/* Short handle + grip */}
      <line x1="12" y1="15.5" x2="12" y2="21" strokeWidth={sw} />
      <line x1="10" y1="22" x2="14" y2="22" strokeWidth={sw} />
    </Svg>
  );
}

/** Football/Soccer — circle with a single FILLED center pentagon. The
 *  radiating seam lines in the previous version were too thin to survive
 *  rendering at 11px; the iconic soccer-ball read is just "circle with a
 *  dark pentagon", which scales down cleanly. */
export function FootballIcon(props: SvgProps) {
  const sw = props.strokeWidth ?? 1.6;
  return (
    <Svg {...props}>
      <circle cx="12" cy="12" r="10" strokeWidth={sw} />
      <polygon
        points="12,7 16.5,10.4 14.7,15.7 9.3,15.7 7.5,10.4"
        fill="currentColor"
        stroke="none"
      />
    </Svg>
  );
}

